window.AP_HUMAN_GEOGRAPHY_DECKS = [{"id":"aphug-unit-1","name":"AP Human Geography · Unit 1","shortName":"Unit 1","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u1-c1","front":"Geographic location","back":"The position of a feature on Earth's surface, described as absolute location using coordinates or relative location in relation to other places.","sourcePage":1},{"id":"aphug-u1-c2","front":"Place as a geographic concept","back":"A location understood through its distinctive physical and human characteristics, including landscape, culture, population, and built environment.","sourcePage":1},{"id":"aphug-u1-c3","front":"Movement of people, goods, and ideas","back":"One of geography's core themes: the spatial transfer of people, commodities, information, and cultural traits between places through migration, trade, communication, and diffusion.","sourcePage":1},{"id":"aphug-u1-c4","front":"Geographic regions","back":"Areas grouped because they share one or more characteristics. Geographers commonly distinguish formal, functional, and perceptual regions.","sourcePage":1},{"id":"aphug-u1-c6","front":"Human Geography","back":"The study of how people, cultures, economies, and political systems are distributed across space and interact with places and environments.","sourcePage":1},{"id":"aphug-u1-c7","front":"Isoline Maps","back":"Use lines of equal value to represent data like elevation, barometric pressure or temperature","sourcePage":2},{"id":"aphug-u1-c8","front":"Choropleth Maps","back":"A thematic map which shows data by shading patterns or colors.","sourcePage":2},{"id":"aphug-u1-c9","front":"Graduated Symbol Map","back":"A thematic map where the size of the symbol is proportionate to the intensity of the data or variable being mapped.","sourcePage":2},{"id":"aphug-u1-c10","front":"Dot Map","back":"A thematic map where the amount of dots represents the frequency of that data or variable.","sourcePage":2},{"id":"aphug-u1-c11","front":"Cartogram","back":"A thematic map that uses the size of a political unit to display the value of a piece of data.","sourcePage":2},{"id":"aphug-u1-c25","front":"Mercator","back":"Distorts shape and size of land masses, good direction and maintains distance, used for sea travel.","sourcePage":3},{"id":"aphug-u1-c26","front":"Robinson","back":"Spread distortion across shape, size, and direction, shows landforms correctly, proportional, poles are shown as a straight line, poles are also flat but are too large, longitude not parallel.","sourcePage":3},{"id":"aphug-u1-c27","front":"Gall-peters projection","back":"Sizes of land masses are accurate, shows correct geographic relationships better, inaccurate distances, distorted shapes, latitude and longitude are parallel.","sourcePage":3},{"id":"aphug-u1-c29","front":"Winkel Tripel projection","back":"Rounder in shape with distortion near north and south poles.","sourcePage":3},{"id":"aphug-u1-c37","front":"Cartography","back":"Science of mapmaking, 1st map made by Eratosthenes (276-194 BC), Ptolemy and later chinese and europe continues to advance.","sourcePage":4},{"id":"aphug-u1-c38","front":"Reference maps","back":"Maps designed to show locations of geographic features such as boundaries, roads, cities, rivers, and terrain rather than a single statistical theme.","sourcePage":4},{"id":"aphug-u1-c39","front":"Map scale","back":"Level of detail and the amount of area covered, ex- 1:24,000 / 1in - 1 mile / bar line","sourcePage":4},{"id":"aphug-u1-c40","front":"Scale","back":"The relationship between distance on a map and the corresponding distance on Earth; scale can also mean the geographic level at which a process is analyzed.","sourcePage":4},{"id":"aphug-u1-c41","front":"small scale","back":"A map scale showing a large area with relatively little detail, such as a world map; its representative fraction has a relatively large denominator.","sourcePage":4},{"id":"aphug-u1-c42","front":"large scale","back":"1/25,000 (less distribution, zoomed in), national, global, regional, county scales","sourcePage":4},{"id":"aphug-u1-c43","front":"Scale of analysis","back":"Observational data at a global, national, regional, and local scale; how data is organized and presented on map. - Ex: If the map of the world has countries in different colors, the map scale is global, but the scale of analysis is national because it's coloring different countries.","sourcePage":4},{"id":"aphug-u1-c44","front":"Scale of inquiry","back":"Asking what best scale of analysis would be for a certain topic, how data is grouped together.","sourcePage":4},{"id":"aphug-u1-c45","front":"Absolute distance","back":"Distance in quantitative terms; such as miles or kilometers.","sourcePage":5},{"id":"aphug-u1-c46","front":"Relative distance","back":"Qualitative distance; such as 20 min south, 30 min north, description of place.","sourcePage":5},{"id":"aphug-u1-c47","front":"Clustering","back":"A spatial distribution in which features are concentrated close together rather than evenly dispersed.","sourcePage":5},{"id":"aphug-u1-c48","front":"Dispersal","back":"A spatial distribution in which features are spread apart across an area.","sourcePage":5},{"id":"aphug-u1-c49","front":"Meridians","back":"Run between the North and South poles; 0 degrees (prime meridian) to 180 degrees east/west longitude","sourcePage":5},{"id":"aphug-u1-c50","front":"Parallels","back":"Form right Ls with meridians; latitude; 0 degrees (equator) to 90 North/South. - 24 time zones. 360/24 - 15 degrees, time zone changes every 15 degrees longitude","sourcePage":5},{"id":"aphug-u1-c51","front":"Greenwich mean time (GMT)","back":"At the prime meridian in Greenwich England, master reference time for all points on earth.","sourcePage":5},{"id":"aphug-u1-c52","front":"GPS","back":"Absolute mathematical position; satellites in orbit, tracking stations to monitor, receiver satellites.","sourcePage":5},{"id":"aphug-u1-c53","front":"GIS","back":"A Geographic Information System: computer hardware and software used to store, layer, analyze, and visualize spatial data.","sourcePage":5},{"id":"aphug-u1-c54","front":"Site of a place","back":"The physical characteristics of a location itself, such as terrain, climate, water access, vegetation, and natural resources.","sourcePage":5},{"id":"aphug-u1-c55","front":"Situation of a place","back":"A location's position relative to other places and networks, including transportation routes, markets, resources, and neighboring settlements.","sourcePage":5},{"id":"aphug-u1-c56","front":"Formal region","back":"A uniform homogeneous region; everywhere has one common trait with distinct boundaries separating itself from other regions; may be predominant characteristic rather than universal; Ex: political organization, language, climate.","sourcePage":5},{"id":"aphug-u1-c57","front":"Functional region","back":"Nodal, has a center and characteristics diffuse outward, no function or region; Ex: circulation of a newspaper, pizza delivery, railroad systems, shopping malls","sourcePage":5},{"id":"aphug-u1-c58","front":"Perceptual region","back":"Vernacular, people believe the region exists due to their cultural identity, Ex: Midwest of the United States","sourcePage":5},{"id":"aphug-u1-c59","front":"Culture","back":"What people care about (beliefs, values); what people take care of (materials)","sourcePage":5},{"id":"aphug-u1-c60","front":"Archipelago","back":"A chain or group of islands located close together, such as Japan, Indonesia, or the Philippines.","sourcePage":5},{"id":"aphug-u1-c61","front":"Spatial distribution","back":"The arrangement of a phenomenon across Earth's surface, analyzed through its density, concentration, and pattern.","sourcePage":5},{"id":"aphug-u1-c62","front":"Density","back":"The frequency with which a feature occurs within a defined area, commonly calculated as a count divided by area.","sourcePage":6},{"id":"aphug-u1-c63","front":"Concentration","back":"The extent to which a phenomenon is clustered or dispersed within an area.","sourcePage":6},{"id":"aphug-u1-c64","front":"Spatial pattern","back":"The geometric or geographic arrangement of phenomena across space, such as clustered, dispersed, linear, or random distributions.","sourcePage":6},{"id":"aphug-u1-c65","front":"Relocation diffusion","back":"Spreads through the physical movement of people; Ex: language is brought to new locale by migrants.","sourcePage":6},{"id":"aphug-u1-c66","front":"Expansion diffusion","back":"The spread of a trait outward from its source while it remains influential there; it includes contagious, hierarchical, and stimulus diffusion.","sourcePage":6},{"id":"aphug-u1-c67","front":"Hierarchical diffusion","back":"The spread of a trait through influential people, institutions, or major nodes before it reaches other groups or places.","sourcePage":6},{"id":"aphug-u1-c68","front":"Contagious diffusion","back":"The rapid, widespread diffusion of a trait through direct contact among nearby people or places, without regard to social hierarchy.","sourcePage":6},{"id":"aphug-u1-c69","front":"Stimulus diffusion","back":"The spread of an underlying idea when the original trait itself is rejected or modified to fit a new cultural setting.","sourcePage":6},{"id":"aphug-u1-c70","front":"Reverse hierarchical diffusion","back":"Lower class characteristics spread to higher classes, Ex: hip hop, sagging pants","sourcePage":6},{"id":"aphug-u1-c71","front":"Distance decay","back":"The decrease of an effect due to distance Wallerstein’s three part theory of core-periphery model","sourcePage":6},{"id":"aphug-u1-c72","front":"Core countries","back":"In world-systems theory, wealthy, highly industrialized countries that dominate global trade, finance, technology, and decision-making.","sourcePage":6},{"id":"aphug-u1-c73","front":"Peripheral countries","back":"In world-systems theory, less-developed countries that often supply raw materials and low-cost labor to the global economy.","sourcePage":6},{"id":"aphug-u1-c74","front":"Semi-periphery countries","back":"Argentina, China, Brazil, Mexico, Iran, Indonesia","sourcePage":6},{"id":"aphug-u1-c75","front":"International scale of analysis","back":"A geographic level of analysis that compares or examines relationships among multiple countries.","sourcePage":6},{"id":"aphug-u1-c76","front":"National scale of analysis","back":"Focuses on economic change in a single country Rostow’s Stages of Economic growth: - 5 stages - Key vocab: mass consumption, drive to maturity, traditional society, take off (stage 3)","sourcePage":6},{"id":"aphug-u1-c77","front":"Space time compression","back":"The time it takes for something to reach another place, increasing connectivity, reduces distance decay. Pattern - The geometric arrangement of objects in space","sourcePage":7},{"id":"aphug-u1-c83","front":"Environmental determinism","back":"Physical environment causes social development, environment causes success of a place; increasing for LDCs (least developed countries) before the 2nd and 3rd industrial revolution.","sourcePage":7},{"id":"aphug-u1-c84","front":"Possibilism","back":"People control the environment to a high extent, Ex: Netherlands were built on polders to keep an island above water, Florida can drain everglades and present pollution.","sourcePage":7},{"id":"aphug-u1-c87","front":"Climate","back":"The long-term average pattern of temperature, precipitation, winds, and other atmospheric conditions in a region.","sourcePage":7},{"id":"aphug-u1-c88","front":"Qualitative data","back":"Opinion based, not measurable; Ex: surveys, polls, interviews","sourcePage":7},{"id":"aphug-u1-c89","front":"Census","back":"Every 10 years is an official count of individuals in a population and collection of geographic data. (how federal funding is determined, helps with moving counties)","sourcePage":7}],"questions":[],"feynmanPrompts":[]},{"id":"aphug-unit-2","name":"AP Human Geography · Unit 2","shortName":"Unit 2","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u2-c1","front":"Contraception","back":"This may go against religious/ cultural beliefs such as roman catholics, fundamentalist protestants, muslims, hindus.","sourcePage":9},{"id":"aphug-u2-c2","front":"Pro-natalist/expansive","back":"Encourages births, Ex: the USSR in 1944 gave awards to women for getting pregnant in order to increase fertility rate, Germany has cross of honor with the german mother on it, India uses family planning","sourcePage":10},{"id":"aphug-u2-c3","front":"Anti-natalist/restrictive","back":"Discourages births, Ex: Chinese had the Later, Longer, Fewer (fewer children, 2 kids allowed in cities, 3 in rural) policy and the one child policy (received rewards: free medical care, schooling, bonuses, etc.)(disobeying results in penalties: education and medical guarantees are withdrawn, wages reduced) 11 Laws of Migration: Most migrants only go a short distance Migration proceeds step by step Migrants going long distance prefer big cities Each migration stream produces a compensation…","sourcePage":10},{"id":"aphug-u2-c4","front":"refugee","back":"has been forced to migrate to avoid a potential threat to his or her life, and or she cannot return for fear of persecution.","sourcePage":11},{"id":"aphug-u2-c5","front":"internally displaced person (IDP)","back":"is similar to a refugee, but he or she has not across an international border.","sourcePage":11},{"id":"aphug-u2-c6","front":"asylum seeker","back":"is a migrant who is looking to be a refugee of another country.","sourcePage":11},{"id":"aphug-u2-c7","front":"Ecumene","back":"Places of permanent human settlement, only a little of the world, 5000 BC to 1900.","sourcePage":11},{"id":"aphug-u2-c10","front":"Carrying capacity","back":"The largest population an environment can support over time without degrading the resource base needed to sustain it.","sourcePage":11},{"id":"aphug-u2-c11","front":"Agricultural density","back":"Ratio of the quantity of famers to amount of arable land (farmers divided by arable land); the US and Canada have a smaller agricultural density than India and Bangladesh, shows amount and advancement of technology being employed, one person can produce more with better machines.","sourcePage":11},{"id":"aphug-u2-c12","front":"Arithmetic density","back":"Total number of objects in an area (total population divided by total land) easiest to get and most frequently used; how unfolded people are; HIGH - a lot of people but little land.","sourcePage":12},{"id":"aphug-u2-c13","front":"Physiological density","back":"The number of people per unit of arable land, used to estimate the pressure a population places on land capable of producing food.","sourcePage":12},{"id":"aphug-u2-c14","front":"Crude Birth Rate (CBR)","back":"The annual number of live births per 1,000 people in a population.","sourcePage":12},{"id":"aphug-u2-c15","front":"Crude Death Rate (CDR)","back":"The annual number of deaths per 1,000 people in a population.","sourcePage":12},{"id":"aphug-u2-c16","front":"Natural increase rate (NIR)","back":"Curious about which population grows, CBR-CDR-NIR, (per 100 because it is a percentage, not per 1,000 people), average current NIR is 1.2%; highest NIR is in South West Asia and Africa.","sourcePage":12},{"id":"aphug-u2-c17","front":"Infant mortality rate (IMR)","back":"Annual number of infant (under 1 years old) deaths per 1,000.","sourcePage":12},{"id":"aphug-u2-c18","front":"Total fertility rate (TFR)","back":"The average number of children a woman is expected to have during her reproductive years, assuming current age-specific birth rates continue.","sourcePage":12},{"id":"aphug-u2-c19","front":"Life expectancy","back":"Average number of years a baby will live based off mortality rates","sourcePage":12},{"id":"aphug-u2-c20","front":"Doubling time","back":"The amount of time it takes for a single population to double in size.","sourcePage":12},{"id":"aphug-u2-c21","front":"Dependency ratio","back":"Number of individuals too old or too young to figure compared to the quantity that may (14 and younger and 65 and older); the larger the dependency ratio the more burden there's on the working population; Ex: 85% Africa, 47% Europe.","sourcePage":12},{"id":"aphug-u2-c22","front":"Sex ratio","back":"Number of males per 100 females, developed countries have more females which live longer. - A population model of male and females can show the culture of a state or a historical event.","sourcePage":12},{"id":"aphug-u2-c23","front":"Malthusian theory","back":"Thomas Malthus's theory that population can grow geometrically while food production grows only arithmetically, creating checks such as famine, disease, and conflict unless population growth slows.","sourcePage":12},{"id":"aphug-u2-c24","front":"Neo-malthusians","back":"Believe earth’s resources can only support a finite population, but they think about all resources not only food production.","sourcePage":13},{"id":"aphug-u2-c26","front":"Immigration","back":"Movement into a country or region for temporary or permanent residence.","sourcePage":13},{"id":"aphug-u2-c27","front":"Emigration","back":"Movement out of a country or region to reside elsewhere.","sourcePage":13},{"id":"aphug-u2-c28","front":"Migration","back":"Temporary (possibly permanent) move from one place to another. - #1 reason to maneuver is to search out jobs","sourcePage":13},{"id":"aphug-u2-c29","front":"Intervening obstacle","back":"Environmental or cultural element that stops migration.","sourcePage":13},{"id":"aphug-u2-c30","front":"Intervening opportunity","back":"Cultural, economic, political, environmental factor that causes an individual to prevent migrating to their original destination.","sourcePage":13},{"id":"aphug-u2-c33","front":"Gravity model","back":"Greater pull in larger communities, bigger cities receive more immigrants.","sourcePage":13},{"id":"aphug-u2-c34","front":"Step migration","back":"Occurs little by little, migrants stop at places along the thanks to their final destination.","sourcePage":13},{"id":"aphug-u2-c35","front":"Chain migration","back":"Process within which legal immigrants may sponsor a loved one for immigration into the US.","sourcePage":13},{"id":"aphug-u2-c36","front":"Intraregional migration","back":"Permanent movement from one location to another within the same region of a country.","sourcePage":13},{"id":"aphug-u2-c37","front":"Xenophobia","back":"Hatred of foreigners based on stereotypes, prejudice, and racism.","sourcePage":13},{"id":"aphug-u2-c38","front":"Counterurbanization","back":"Most prevalent in places rich with natural amenities; Ex: range of mountains States (Colorado, Idaho, Utah, and Wyoming)","sourcePage":13},{"id":"aphug-u2-c40","front":"Interregional migration","back":"Movement from one region to a different region within the same country; Ex: Abundant land on the old american frontier, most jobs and services in are clustered urban areas. Interregional migration - Movement from one region to another region in the same country; Ex: Abundant of land on the old american frontier, most jobs and services in are clustered urban areas. - Russia: Interregional migration was encouraged by the government. The government built new factores and has other economic…","sourcePage":14},{"id":"aphug-u2-c41","front":"Remittances","back":"Money migrants earn in a destination and send to family members or communities in their place of origin.","sourcePage":14},{"id":"aphug-u2-c42","front":"Brain drain","back":"Loss of skilled educated workers. - Largest number of refugees originated from Southwest Asia and sub-saharan Africa. - Preference shown for specific employment placement and family reunification.","sourcePage":14}],"questions":[],"feynmanPrompts":[]},{"id":"aphug-unit-3","name":"AP Human Geography · Unit 3","shortName":"Unit 3","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u3-c1","front":"Folk Culture","back":"Popular Culture Other/Mixed Isolated group practicing the Large group of diverse Sports originated as isolated people sharing similar same culture, Ex: amish folk customs and diffused behavior people like other folk cultures via relocation diffusion. - Usually transmitted - Smaller scale and through hierarchical - Football (or soccer) slower transmissions diffusion came from England in from one location to - Diffuses rapidly and the 11th century. another primarily - Transformation from through…","sourcePage":15},{"id":"aphug-u3-c2","front":"Popular Culture","back":"Other/Mixed Large group of diverse Sports originated as isolated people sharing similar folk customs and diffused behavior like other folk cultures via relocation diffusion. - Usually transmitted through hierarchical - Football (or soccer) diffusion came from England in - Diffuses rapidly and the 11th century. - Transformation from extensively from folk to popular sport hearths or nodes of began in the 1800s innovation with help when organized clubs of modern communication, were formed in the…","sourcePage":15},{"id":"aphug-u3-c11","front":"Language as a cultural trait","back":"A structured system of communication that carries cultural identity, spreads through migration and diffusion, and can unify or divide places.","sourcePage":19},{"id":"aphug-u3-c12","front":"Indo-European","back":"The world's most widely distributed language family, including the Germanic, Romance, Balto-Slavic, Indo-Iranian, Hellenic, Celtic, and other branches.","sourcePage":19},{"id":"aphug-u3-c13","front":"Sino-Tibetan","back":"A major language family centered in East and Southeast Asia that includes Sinitic languages such as Mandarin and the Tibeto-Burman languages.","sourcePage":20},{"id":"aphug-u3-c14","front":"Afro-Asiatic","back":"A language family spoken mainly across North Africa, the Horn of Africa, and Southwest Asia; major branches include Semitic, Berber, Cushitic, Chadic, and Egyptian.","sourcePage":20},{"id":"aphug-u3-c16","front":"Niger-Congo","back":"A large language family spoken across much of sub-Saharan Africa; it includes the Bantu languages and languages such as Swahili.","sourcePage":20},{"id":"aphug-u3-c18","front":"Germanic branch","back":"An Indo-European language branch that includes English, German, Dutch, Swedish, Danish, Norwegian, and related languages.","sourcePage":20},{"id":"aphug-u3-c19","front":"Indo-Iranian branch","back":"The largest Indo-European branch by number of speakers, containing Indo-Aryan languages such as Hindi and Bengali and Iranian languages such as Persian.","sourcePage":21},{"id":"aphug-u3-c20","front":"Balto-Slavic branch","back":"An Indo-European branch containing Baltic languages such as Lithuanian and Latvian and Slavic languages such as Russian, Polish, Czech, and Serbo-Croatian.","sourcePage":21},{"id":"aphug-u3-c21","front":"Romance branch","back":"An Indo-European language branch descended from Latin, including Spanish, Portuguese, French, Italian, and Romanian.","sourcePage":21},{"id":"aphug-u3-c22","front":"Proto-Indo European","back":"The reconstructed common ancestor of the Indo-European languages, believed to have been spoken thousands of years ago before dispersing into distinct branches.","sourcePage":21},{"id":"aphug-u3-c23","front":"Nomadic warrior theory hypothesis","back":"The hypothesis that Proto-Indo-European speakers originated on the Eurasian steppe and spread their language through migration, conquest, and domesticated horses.","sourcePage":21},{"id":"aphug-u3-c24","front":"Sedentary farmer theory","back":"The hypothesis that early Indo-European languages spread from Anatolia with the gradual diffusion of agriculture and settled farming communities.","sourcePage":21},{"id":"aphug-u3-c25","front":"Universalizing Religions","back":"Roman Catholicism southwest and east Europe, Latin America - Protestantism in northwestern","sourcePage":22},{"id":"aphug-u3-c26","front":"Ethnic Religions","back":"Cremate and burn bodies in ganges river - Largest ethnic religion, most in india - Holy books include the Vedas, Bhagavad Geeta, and Upanishads - Monotheistic religion with many forms","sourcePage":25},{"id":"aphug-u3-c27","front":"Animism","back":"Inanimate objects or natural events like disasters have spirits, common in Africa.","sourcePage":25},{"id":"aphug-u3-c28","front":"Judaism","back":"First abrahamic religion, ⅖ Israel, ⅖ US - Bury dead in cemeteries - Western wailing wall, last wall of solomon's temple","sourcePage":25},{"id":"aphug-u3-c29","front":"Cultural appropriation","back":"The adoption of cultural traits from another group, especially when a dominant group uses elements of a marginalized culture without permission, understanding, or respect for their meaning.","sourcePage":27},{"id":"aphug-u3-c30","front":"Cultural relativism","back":"Evaluating a culture according to its own values and context rather than judging it by the standards of another culture.","sourcePage":27},{"id":"aphug-u3-c31","front":"Cultural landscape","back":"The visible imprint of human activity and culture on the natural landscape, including buildings, land use, language, religion, and settlement patterns.","sourcePage":27},{"id":"aphug-u3-c32","front":"Cultural convergence","back":"Two cultures become more similar from frequent interactions.","sourcePage":27},{"id":"aphug-u3-c33","front":"Cultural divergence","back":"A culture splits due to a lack of connection.","sourcePage":27},{"id":"aphug-u3-c34","front":"Acculturation","back":"Adoption of cultural traits from a larger group while still maintaining the original culture.","sourcePage":27},{"id":"aphug-u3-c35","front":"Assimilation","back":"Killing/removal of culture by learning a new culture to replace the previous.","sourcePage":27},{"id":"aphug-u3-c36","front":"Habit","back":"Repetitive act of an individual. For example, wearing jeans everyday.","sourcePage":27},{"id":"aphug-u3-c37","front":"Postmodern architecture","back":"Began 1960s, combines traditional and contemporary architecture.","sourcePage":27},{"id":"aphug-u3-c38","front":"Terroir","back":"Contribution of a location’s physical features on the way food tastes. Also known as the effects of climate on food.","sourcePage":28},{"id":"aphug-u3-c39","front":"Guest worker","back":"European and German countries allow people to temporarily immigrate into their country for a job. China and Southwest Asia are major destinations for migrants.","sourcePage":28},{"id":"aphug-u3-c40","front":"Literary tradition","back":"A language's established system of writing and written works, which helps standardize and preserve it across time and space.","sourcePage":28},{"id":"aphug-u3-c41","front":"Dialects","back":"The regional variation of a language with distinguished vocab, spelling, and pronunciation. It is greatest in rural areas where people have little interaction.","sourcePage":28},{"id":"aphug-u3-c42","front":"Isogloss","back":"Boundary where words/dialect regions can be mapped out.","sourcePage":28},{"id":"aphug-u3-c43","front":"Logograms","back":"Symbols which represent words rather than sounds.","sourcePage":28},{"id":"aphug-u3-c44","front":"Creole language","back":"Mixing of two or more separate languages, Ex: Afrikaans is a mix of dutch and another African language.","sourcePage":28},{"id":"aphug-u3-c45","front":"Multilingual states","back":"States with more than one official language, Ex: Belgium, Switzerland, Nigeria.","sourcePage":28},{"id":"aphug-u3-c46","front":"Revived language","back":"One that was previously extinct but brought back to use. Ex: Hebrew was revived with modern updates.","sourcePage":28},{"id":"aphug-u3-c47","front":"Lingua franca","back":"Language of international communication, Ex: English, Swahili in east Africa, Hindi in South Asia, Russian in Soviet Union.","sourcePage":28},{"id":"aphug-u3-c52","front":"Secularism","back":"Dividing state from church, Ex: Renaissance era in Europe with the Catholic church.","sourcePage":29},{"id":"aphug-u3-c53","front":"Sense of place","back":"A feeling that an area has a distinct and meaningful character.","sourcePage":29},{"id":"aphug-u3-c54","front":"Zionism","back":"Policy for establishing a homeland for Jews in palestine.","sourcePage":29},{"id":"aphug-u3-c55","front":"Sharia law","back":"Islamic law which varies on the interpretation of the Karan.","sourcePage":29},{"id":"aphug-u3-c56","front":"Interfaith","back":"Relations, dialogue, or activities involving people or institutions from different religions.","sourcePage":29},{"id":"aphug-u3-c57","front":"Intrafaith","back":"Taking place within, or relevant to a single faith community, Ex: intrafaith marriage.","sourcePage":29},{"id":"aphug-u3-c58","front":"Toponym","back":"Something named after culture or landscape, Ex: Quebec, Ontario, Santa Fe.","sourcePage":29},{"id":"aphug-u3-c59","front":"Syncretism","back":"Blending multiple religions, Ex: halloween is Christian and Pagan.","sourcePage":29},{"id":"aphug-u3-c60","front":"Pilgrimage","back":"Journey for religious purposes, Ex: Muslims to travel to Mecca in the Hajj.","sourcePage":29},{"id":"aphug-u3-c61","front":"Utopian settlement","back":"An ideal community that is constructed around a religious life, Ex: Salt Lake City by the Mormons.","sourcePage":29},{"id":"aphug-u3-c62","front":"Fundamentalism","back":"Literal interpretation and strict adherence to basic principles, Ex: the Taliban’s control over Afghanistan’s government led to strict laws opposing western values such as soccer.","sourcePage":29},{"id":"aphug-u3-c63","front":"Autonomous region","back":"No central authority, shares ideas and cooperates informally.","sourcePage":29},{"id":"aphug-u3-c64","front":"Sacred sites","back":"Ex: Kaaba mosque in Mecca, Jerusalem, Salt Lake City for Mormons, Dome of Rock.","sourcePage":29},{"id":"aphug-u3-c65","front":"Race","back":"Categorization of humans based on skin color or other characteristics such as one’s identity with common ancestors.","sourcePage":29},{"id":"aphug-u3-c66","front":"Minority group","back":"Any recognizable group suffering from discrimination.","sourcePage":29},{"id":"aphug-u3-c67","front":"Ethnic groups","back":"Racial groups based on culture or ethnicity, Ex: Asian American title covers many nationalities. Jews are racially diverse but are bound by a common religion.","sourcePage":29},{"id":"aphug-u3-c68","front":"Ethnicity","back":"The identity a group shares based on traditions from their homeland.","sourcePage":29},{"id":"aphug-u3-c69","front":"Ethnic cleansing","back":"One ethnicity removes another to create a homogeneous region, Ex: Bosnian Muslims in former Yugoslavia were eliminated and a diverse Balkan peninsula is created.","sourcePage":30},{"id":"aphug-u3-c70","front":"Diaspora","back":"Dispersion of people from their homeland, Ex: Jews from Israel.","sourcePage":30},{"id":"aphug-u3-c71","front":"Genocide","back":"Mass killing of a population/ethinicty, Ex: Tutsis murdered by Hutus in Rwanda.","sourcePage":30},{"id":"aphug-u3-c72","front":"Apartheid","back":"Physcial spereation of different races into different geogrpahic areas.","sourcePage":30},{"id":"aphug-u3-c73","front":"Nationality","back":"Identity with a group of people who share legal attachment to a country.","sourcePage":30},{"id":"aphug-u3-c74","front":"Ethnic separatism","back":"Desired regional autonomy expressed by a cultural group within a larger dominant culture.","sourcePage":30}],"questions":[],"feynmanPrompts":[]},{"id":"aphug-unit-4","name":"AP Human Geography · Unit 4","shortName":"Unit 4","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u4-c1","front":"Devolution","back":"Movement of power from the central government to the regional government within a state. It is caused by ethnocultural, economic, and spatial forces. For example... - Scotland wants independence from the EU and ownership of oil resources. - Spain (the Basque and Catalonia each want their own economic autonomy) - Belgium - Flemish (Dutch) in the north and Walloons (French) in the south","sourcePage":31},{"id":"aphug-u4-c2","front":"Landlocked states","back":"Lacks direct outlet to sea, surrounded by other countries, Ex: common in africa, belarus, mongolia, chad, paraguay","sourcePage":32},{"id":"aphug-u4-c3","front":"Gerrymandering","back":"Redrawing legislative boundaries to favor the party in power, illegal in 1985 - Wasted vote: Spreads opposition voters across districts so they are the minority. - Excess vote: Concentrates the opposing voters into a few different districts. - Stacked vote: Link areas of like minded voters into oddly shaped boundaries.","sourcePage":32},{"id":"aphug-u4-c4","front":"United Nations Convention on the Law of the Sea (UNCLOS)","back":"The international legal framework governing maritime boundaries and ocean use, including territorial seas, contiguous zones, exclusive economic zones, and the high seas.","sourcePage":32},{"id":"aphug-u4-c5","front":"Territorial sea","back":"Coastal waters extending up to 12 nautical miles from a state's baseline, where the state exercises sovereignty subject to innocent passage.","sourcePage":32},{"id":"aphug-u4-c6","front":"Contiguous zone","back":"Waters extending up to 24 nautical miles from a state's baseline, where it may enforce customs, immigration, fiscal, and sanitation laws.","sourcePage":32},{"id":"aphug-u4-c7","front":"Exclusive Economic Zone (EEZ)","back":"200 nautical miles, state can explore and manage natural resources","sourcePage":32},{"id":"aphug-u4-c8","front":"High seas","back":"Ocean areas beyond national exclusive economic zones that are open to navigation and use by all states under international law.","sourcePage":32},{"id":"aphug-u4-c10","front":"NATO","back":"(North Atlantic Treaty Organization) - 16 democratic states, US, Canada, 14 Europeans, meant to prevent spread of communism of soviets, conflict w/ Muslims","sourcePage":33},{"id":"aphug-u4-c12","front":"United Nations","back":"(+political) - Created at the end of WW2, facilitates discussion of international problems.","sourcePage":33},{"id":"aphug-u4-c13","front":"EU","back":"(European Union) - 27 countries, promote development of members after WW2, made Euro, used to have barriers on trade but those were removed.","sourcePage":33},{"id":"aphug-u4-c16","front":"State (political geography)","back":"A politically organized territory with a permanent population, defined boundaries, a government, and sovereignty over its internal and external affairs.","sourcePage":33},{"id":"aphug-u4-c17","front":"Sovereignty","back":"Inner affairs of a region are independent from control by other states.","sourcePage":33},{"id":"aphug-u4-c18","front":"Nation (political geography)","back":"A group of people who share a strong cultural identity, history, homeland, or political aspirations; a nation does not necessarily control a sovereign state.","sourcePage":33},{"id":"aphug-u4-c19","front":"Nation-state","back":"Population of a country is homogeneous, Ex: Denmark, Slovenia, Japan, Iceland.","sourcePage":33},{"id":"aphug-u4-c20","front":"Stateless nation","back":"Ethnic group without a state, Ex: Kurds in middle east.","sourcePage":33},{"id":"aphug-u4-c21","front":"Microstate","back":"Sovereign state with small population and land, Ex: Monaco.","sourcePage":33},{"id":"aphug-u4-c22","front":"City-state","back":"First states, made of towns and surrounding countryside, walls made to show boundaries, some with military power take over such as the Roman empire, first one arose in Mesopotamia.","sourcePage":34},{"id":"aphug-u4-c23","front":"Self-determination","back":"Concept that ethnicities have the right to govern themselves.","sourcePage":34},{"id":"aphug-u4-c25","front":"Multi-state nation","back":"Nation stretches across borders of states, Ex: north and south Korea.","sourcePage":34},{"id":"aphug-u4-c26","front":"Multi-ethnic state","back":"A sovereign state whose population contains multiple ethnic groups, such as the United States, Canada, or Nigeria.","sourcePage":34},{"id":"aphug-u4-c27","front":"Multinational state","back":"Country with more than one ethnicity with self determination, Ex: Russia’s caucasus region between black and caspian seas with the azeris, armenians, and georgians.","sourcePage":34},{"id":"aphug-u4-c28","front":"Decolonization","back":"Colonial settlements become independent nations, Ex: 13 colonies.","sourcePage":34},{"id":"aphug-u4-c29","front":"Colony","back":"Territory legally tied to state rather than being independent, Ex: puerto rico, not a part of congress but is home to US citizens.","sourcePage":34},{"id":"aphug-u4-c30","front":"Colonialism","back":"Country establishes settlement to impose its politics, economy, and culture on that territory.","sourcePage":34},{"id":"aphug-u4-c31","front":"Imperialism","back":"Control of territory already occupied by another society.","sourcePage":34},{"id":"aphug-u4-c32","front":"Ethnonationalism","back":"Nationalism in which shared ethnic identity supports claims to political autonomy, sovereignty, or an independent state.","sourcePage":34},{"id":"aphug-u4-c33","front":"State morphology","back":"The shape and territorial configuration of a state, commonly categorized as compact, elongated, prorupted, perforated, or fragmented.","sourcePage":34},{"id":"aphug-u4-c38","front":"Organic theory","back":"Theory that states are born and they need nourishment and living space to survive.","sourcePage":34},{"id":"aphug-u4-c39","front":"Heartland theory","back":"Mackinder, early 1900s, best base for world domination is the eurasian heartland.","sourcePage":35},{"id":"aphug-u4-c40","front":"Rimland theory","back":"Spykman, 1944, best base for global domination is eurasian rimland.","sourcePage":35},{"id":"aphug-u4-c41","front":"Choke point","back":"A geographical land feature such as a valley or water way narrowing causing a decrease in forces making their way through.","sourcePage":35},{"id":"aphug-u4-c42","front":"Centripetal forces","back":"Bind or hold together, ex: strong leadership, external threat, education, democracy, russian language for soviet union.","sourcePage":35},{"id":"aphug-u4-c43","front":"Centrifugal forces","back":"Divide or tear state, devolutionary forces, ex: culture/religious/linguistic differences. State - Formal name for country, defined bordes, sovereign gov, recognized, permanent population.","sourcePage":35},{"id":"aphug-u4-c44","front":"Democracy","back":"A political system in which citizens exercise sovereignty directly or through elected representatives in competitive, meaningful elections.","sourcePage":35},{"id":"aphug-u4-c45","front":"Autocracy","back":"A political system in which one ruler or a small group holds concentrated power with limited public participation or institutional restraint.","sourcePage":35},{"id":"aphug-u4-c46","front":"Anocracy","back":"A mixed or transitional political system combining democratic and authoritarian characteristics.","sourcePage":35},{"id":"aphug-u4-c47","front":"Unitary system","back":"Centralized control, no local power, works best in nation states with less cultural differences, smaller states, ex: france, european countries, north korea, kenya, rwanda, china.","sourcePage":35},{"id":"aphug-u4-c48","front":"Confederal systems","back":"Less central power, lots of power to states, confederate states","sourcePage":35},{"id":"aphug-u4-c49","front":"Federal systems","back":"Between unitary and confederal, ex: United states, canada, brazil, india, belgium.","sourcePage":35},{"id":"aphug-u4-c50","front":"Reapportionment","back":"Assigning representation based on population every census.","sourcePage":35},{"id":"aphug-u4-c51","front":"Redistricting","back":"Redrawing district boundaries so each district contains the same amount of people.","sourcePage":35},{"id":"aphug-u4-c53","front":"Border conflicts","back":"Positional, territorial, resource, functional.","sourcePage":35},{"id":"aphug-u4-c54","front":"Shatterbelt","back":"Distress bc of cultural/ethnic conflict, ex: israel, kashmir, east europe during cold war.","sourcePage":35},{"id":"aphug-u4-c55","front":"Cultural boundaries","back":"Geometric (straight line drawn on map, canada and US border), religious, language, ethnic (england,france,portugal,spain boundaries, bc of language or religion), Ex: pakistan and india.","sourcePage":36},{"id":"aphug-u4-c56","front":"Delimited boundary","back":"States disagree about interpretation of documents that define a boundary, Ex: Argentina and Chile's borders on the Andes mountains, drawn on map to show limits of space.","sourcePage":36},{"id":"aphug-u4-c57","front":"Antecedent boundary","back":"Result of area becoming population and gaining value, existed before present settlement occurred and the culture arrived, Ex: US and canada, Ohio R.","sourcePage":36},{"id":"aphug-u4-c58","front":"Subsequent boundary","back":"Developed with the evolution of cultural change, Ex: irsh catholic and pretestant northern ireland, velvet divorce in Czechoslovakia.","sourcePage":36},{"id":"aphug-u4-c62","front":"Superimposed boundary","back":"Political, dividing ethnically similar population by a more powerful country, cause loss of culture, creation of new culture, migration, government change, ineffective governance, multi state nation, multinational state Ex: Kurds in Turkey, Iraq, Iran, and Africa in the Berlin Conference.","sourcePage":36},{"id":"aphug-u4-c63","front":"Relic boundary","back":"Historic boundary, no longer used/nonfunctional, Ex:berlin wall germany, great wall China.","sourcePage":36},{"id":"aphug-u4-c66","front":"Geometric boundary","back":"Straight line, doesn’t follow physical features, large-egypt and libya, small-suburbs.","sourcePage":36},{"id":"aphug-u4-c67","front":"Irredentism","back":"Country wants to annex similarly ethnic portion of another country, Ex: Hitler invading czechoslovakia, Somalia - ethiopia conflict over somalis, serbians in bosnia, kashmir region in india, reich trying to connect all german speaking people in europe.","sourcePage":36},{"id":"aphug-u4-c73","front":"Enclaves","back":"Country or part of a country surrounded by territory of another, Ex: lesotho.","sourcePage":37},{"id":"aphug-u4-c74","front":"Exclaves","back":"Parts of a state separated from its main territory by another state or states; an exclave may also be an enclave if it is completely surrounded by one country.","sourcePage":37},{"id":"aphug-u4-c75","front":"Forward capital","back":"Capital city positioned near the international border, confirms the state’s determination to maintain presence. - Capitals that moved somewhere after 1950: Brazil, Nigeria, Pakistan.","sourcePage":37},{"id":"aphug-u4-c76","front":"Geopolitics","back":"Study of interplay between international political relations and environmental context.","sourcePage":37},{"id":"aphug-u4-c77","front":"Supranationalism","back":"3 or more countries form unions for economic, political or cultural reasons.","sourcePage":37},{"id":"aphug-u4-c78","front":"Terrorism","back":"Systematic use of violence to indimidate populations, Ex: 9-11, afrghanistan and pakistan harbor al-qaeda terrorists.","sourcePage":37}],"questions":[],"feynmanPrompts":[]},{"id":"aphug-unit-5","name":"AP Human Geography · Unit 5","shortName":"Unit 5","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u5-c2","front":"Extensive agriculture","back":"has limited labor input and extends across large areas of land","sourcePage":42},{"id":"aphug-u5-c3","front":"Intensive agriculture","back":"Involves labor inputs and focuses on small sections of land. - In prehistoric times, the earliest forms of agriculture emerged from hunting and gathering societies.","sourcePage":42},{"id":"aphug-u5-c4","front":"Pastoralism","back":"Agriculture that is based on seasonal movements of animals. - Also known as nomadic herding","sourcePage":42},{"id":"aphug-u5-c5","front":"Cultivars","back":"The practice of producing plants by selective breeding.","sourcePage":42},{"id":"aphug-u5-c6","front":"Multiple cropping","back":"Harvesting more than one crop from the same field during a single year, usually where long growing seasons and sufficient moisture permit it.","sourcePage":42},{"id":"aphug-u5-c7","front":"Staple crop","back":"food is eaten regularly or is apart of the standard diet - Ex: wheat","sourcePage":42},{"id":"aphug-u5-c9","front":"Mixed farming","back":"Crop farmers domesticated animals to their holdings.","sourcePage":42},{"id":"aphug-u5-c10","front":"Subsistence agriculture","back":"Mixed farming which provides all the necessary items for a household.","sourcePage":42},{"id":"aphug-u5-c11","front":"Extensive subsistence agriculture","back":"This happens when there are a low amount of labor inputs per unit of land.","sourcePage":42},{"id":"aphug-u5-c13","front":"Arable land","back":"Land suitable for cultivation and crop production.","sourcePage":42},{"id":"aphug-u5-c15","front":"Specialized crop","back":"A crop produced for a particular market or growing environment rather than as part of broadly diversified farming, such as fruit, vegetables, or nuts.","sourcePage":42},{"id":"aphug-u5-c16","front":"Cash-cropping","back":"Opposite of intensive subsistence farming Extensive agriculture - Crops exchanged for goods, credit, and money.","sourcePage":42},{"id":"aphug-u5-c17","front":"Commercial crop","back":"Transported and sold at markets and then processed into other goods and put on sale. - Crop used for domestic consumption and export.","sourcePage":42},{"id":"aphug-u5-c18","front":"Plantation agriculture","back":"A commercial farming technique where a single crop is grown for the entire year","sourcePage":42},{"id":"aphug-u5-c24","front":"Crop Rotation","back":"A planned sequence of different crops on the same field across seasons to maintain soil fertility and reduce pests, diseases, and erosion.","sourcePage":43},{"id":"aphug-u5-c25","front":"Double cropping","back":"Planting two crops one after another in the same plot (within 1 year).","sourcePage":43},{"id":"aphug-u5-c26","front":"Triple cropping","back":"Three crops being planted in a single plot in the same year.","sourcePage":43},{"id":"aphug-u5-c27","front":"Growing season","back":"Every individual crop has its season in which it grows.","sourcePage":43},{"id":"aphug-u5-c30","front":"Irrigation","back":"The artificial delivery of water to crops or soil when rainfall is insufficient or unreliable.","sourcePage":43},{"id":"aphug-u5-c31","front":"Aquifers","back":"In countries such as India they are being depleted at rapid rates.","sourcePage":43},{"id":"aphug-u5-c32","front":"Conservation","back":"The practice of preserving and managing natural resources.","sourcePage":43},{"id":"aphug-u5-c33","front":"Conservation agriculture","back":"Becomes important to provide a sustainable farming system without sparing any crop productions.","sourcePage":43},{"id":"aphug-u5-c34","front":"Interplanting","back":"The farmer is allowed to harvest fast-growing crops before the slower ones.","sourcePage":43},{"id":"aphug-u5-c35","front":"Sustainable yield","back":"The # of crops/animals that can be raised with endangering loc resources such as: - Soil - Irrigation - Groundwater","sourcePage":43},{"id":"aphug-u5-c36","front":"Sustainability","back":"Using resources to meet present needs while maintaining environmental systems and future generations' ability to meet their needs.","sourcePage":43},{"id":"aphug-u5-c39","front":"Slash and burn agriculture","back":"Farmers shifting one plot of land to another every few years.","sourcePage":44},{"id":"aphug-u5-c40","front":"Fallow","back":"Cultivated land deliberately left unplanted for a period so soil moisture and fertility can recover.","sourcePage":44},{"id":"aphug-u5-c41","front":"Extensive pastoralism","back":"The shifting of animal herds between grazing pastures. - Used in Africa, Middle East, Central Asia","sourcePage":44},{"id":"aphug-u5-c42","front":"Overgrazing","back":"Led to significant amounts of dry grassland being eroded.","sourcePage":44},{"id":"aphug-u5-c43","front":"Soil salinization","back":"Occurs in arid regions where water evaporates which leaves salts behind.","sourcePage":44},{"id":"aphug-u5-c44","front":"Vegetative planting","back":"Shoots, stems, and roots of wild plants are collected and grown together.","sourcePage":44},{"id":"aphug-u5-c45","front":"Seed agriculture","back":"Fertilized seed grains and fruits are collected and planted together.","sourcePage":44},{"id":"aphug-u5-c46","front":"Domestication of plants","back":"The deliberate selection and cultivation of wild plants for useful traits, a key development of the Neolithic agricultural revolution.","sourcePage":44},{"id":"aphug-u5-c47","front":"Horticulture","back":"Plant varieties thrived in various soil and climate conditions were to be cultivated.","sourcePage":44},{"id":"aphug-u5-c48","front":"Animal domestication","back":"Animals are tamed and used for food and profit.","sourcePage":44},{"id":"aphug-u5-c49","front":"Animal husbandry","back":"A branch of agriculture focused on the animals. They are raised for meat, fiber, milk, eggs, and more.","sourcePage":44},{"id":"aphug-u5-c50","front":"The Columbian Exchange","back":"Voyages of Christopher Columbus brought some of the diffusion of animals","sourcePage":44},{"id":"aphug-u5-c52","front":"Chemical Fertilizers","back":"Manufactured substances added to soil to supply plant nutrients, especially nitrogen, phosphorus, and potassium.","sourcePage":44},{"id":"aphug-u5-c53","front":"Chemical pesticides","back":"Synthetic chemicals used to control insects, weeds, fungi, and other organisms that damage crops.","sourcePage":44},{"id":"aphug-u5-c54","front":"Mechanization","back":"The replacement or supplementation of human and animal labor with machinery in agriculture or industry.","sourcePage":44},{"id":"aphug-u5-c55","front":"Dwarf varieties","back":"Shorter breeds of both wheat and rice were found to be harder and more productive, because the plant spent less time and energy growing a stalk resulting in larger grains.","sourcePage":45},{"id":"aphug-u5-c56","front":"Green Revolution","back":"tropical plant, animal hybrids, and chemical fertilizers began to be used in Third-World agriculture","sourcePage":45},{"id":"aphug-u5-c59","front":"Genetic Engineering","back":"Humans altering an organism's genes also known as genetic modification/manipulation. - Ex: BT corn","sourcePage":45},{"id":"aphug-u5-c60","front":"Biotechnology","back":"The use of living organisms, cells, or biological processes to develop products or alter crops and livestock.","sourcePage":45},{"id":"aphug-u5-c61","front":"Factory farming","back":"Large-scale, intensive livestock production in confined facilities designed to maximize output, also called industrial animal agriculture.","sourcePage":45},{"id":"aphug-u5-c63","front":"Extensive monoculture of Staple crops","back":"Large-scale cultivation of a single staple crop, such as wheat, corn, or soybeans, over a broad area using mechanized methods.","sourcePage":45},{"id":"aphug-u5-c64","front":"Commodity prices","back":"A good that can be traded for products that have similar value.","sourcePage":45},{"id":"aphug-u5-c65","front":"Corporate agriculture or agribusiness","back":"Large extensive farms controlled by single regional business.","sourcePage":45},{"id":"aphug-u5-c67","front":"GMOs","back":"Genetically modified organisms whose DNA has been altered using genetic engineering to introduce desired traits.","sourcePage":45},{"id":"aphug-u5-c68","front":"Organic","back":"products free of - Pesticides - Antibiotics - Synthetic hormones - Fertilizers","sourcePage":45},{"id":"aphug-u5-c69","front":"Cottage Industry","back":"A traditional type of manufacturing practice by individuals and produced handmade goods for local consumption in the industrial era.","sourcePage":46},{"id":"aphug-u5-c73","front":"Truck Farms","back":"grow specialty crop during the summer growing season","sourcePage":46},{"id":"aphug-u5-c74","front":"Mediterranean agriculture","back":"domesticated crops - Citrus - oranges, lemons, limes, grapefruit, blood oranges - Nut trees - pistachio, almonds - Palms - different varieties produce fates, palm oils, hearts of palm - Olives - varies both used for eating and pressing for oil - Artichokes - flowers that are fresh for cooking or hearts preserved in oil - Avocados - dark-skinned, has variety and larger green Florida type - Grapes - raisins and fresh fruits pressed for wine production","sourcePage":46},{"id":"aphug-u5-c75","front":"Milk shed","back":"Delivery of fresh milk in surrounding areas of production.","sourcePage":46},{"id":"aphug-u5-c77","front":"Johann Heinrich von Thunen","back":"wrote The Isolated State in 1826 - A described pattern of agricultural land","sourcePage":46},{"id":"aphug-u5-c79","front":"Von Thunen's model","back":"A land-use model in which agricultural activities form rings around a market according to transportation cost, perishability, and land value.","sourcePage":46}],"questions":[],"feynmanPrompts":[]},{"id":"aphug-unit-6","name":"AP Human Geography · Unit 6","shortName":"Unit 6","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u6-c3","front":"Renewable resource","back":"A resource replenished naturally on a human time scale when managed sustainably, such as solar energy, wind, forests, or freshwater.","sourcePage":47},{"id":"aphug-u6-c10","front":"GNI at purchasing power parity (PPP)","back":"Gross national income adjusted for differences in local prices, allowing standards of living and purchasing power to be compared more meaningfully across countries.","sourcePage":51},{"id":"aphug-u6-c13","front":"Manufacturing","back":"Secondary-sector activity that transforms raw materials or components into finished or semi-finished products.","sourcePage":51},{"id":"aphug-u6-c17","front":"Resource-dependent country","back":"A country whose exports, government revenue, or employment relies heavily on a narrow range of natural resources.","sourcePage":51},{"id":"aphug-u6-c20","front":"Non-Renewable","back":"A resource that forms too slowly to be replaced on a human time scale, including fossil fuels and most mineral deposits.","sourcePage":51},{"id":"aphug-u6-c21","front":"Renewable","back":"An energy resource replenished naturally on a human time scale, such as solar, wind, hydroelectric, geothermal, or tidal energy.","sourcePage":51},{"id":"aphug-u6-c22","front":"Alternative energy","back":"Energy sources used in place of conventional fossil fuels, often including solar, wind, geothermal, tidal, and nuclear power.","sourcePage":51},{"id":"aphug-u6-c23","front":"Sustainable resource use","back":"Managing renewable resources at a rate that allows replenishment and preserves ecosystem functions and biodiversity over time.","sourcePage":51},{"id":"aphug-u6-c24","front":"Ecosystem","back":"A community of organisms interacting with one another and with the nonliving environment as a connected system.","sourcePage":52},{"id":"aphug-u6-c25","front":"Value-added processing","back":"The transformation of raw goods to more valuable goods.","sourcePage":52},{"id":"aphug-u6-c29","front":"Deindustrialized","back":"A shift from manufacturing being the main source of economic production.","sourcePage":52},{"id":"aphug-u6-c30","front":"Foreign competition","back":"A competition involving all countries worldwide.","sourcePage":52},{"id":"aphug-u6-c33","front":"Restructuring","back":"Reorganization of the system to adapt to changes in the economy.","sourcePage":53},{"id":"aphug-u6-c34","front":"Free-market reforms","back":"An economic system based on supply and demand and has little government control.","sourcePage":53},{"id":"aphug-u6-c35","front":"Newly industrialized countries","back":"States with economies that have made districts shift away from agriculture and towards manufacturing.","sourcePage":53},{"id":"aphug-u6-c36","front":"Infrastructure","back":"The basic systems supporting society and economic activity, including transportation, energy, water, sanitation, and communications networks.","sourcePage":53},{"id":"aphug-u6-c37","front":"Foreign aid or foreign direct investment (FDI)","back":"Funds to develop infrastructure and factories that come from internal sources.","sourcePage":53},{"id":"aphug-u6-c38","front":"Developmental loans","back":"Funds lent by governments or international institutions for infrastructure, education, health, or economic development projects.","sourcePage":53},{"id":"aphug-u6-c40","front":"Technology transfer","back":"technical knowledge, training is provided to NIC governments to increase business efficiency","sourcePage":53},{"id":"aphug-u6-c41","front":"World Bank","back":"seeks international development loans that build infrastructure","sourcePage":53},{"id":"aphug-u6-c42","front":"Comparative advantage","back":"The ability of a country or region to produce a good or service at a lower opportunity cost than another producer.","sourcePage":53},{"id":"aphug-u6-c43","front":"Offshoring","back":"Relocating a business process, service, or production activity to another country, often to reduce costs or reach new markets.","sourcePage":53},{"id":"aphug-u6-c48","front":"Uneven development","back":"The increasing gap between developmental, technology, and poor stands of living.","sourcePage":54},{"id":"aphug-u6-c49","front":"GNI","back":"(gross national income) - Is the dollar value of all goods and services and the value of exports minus imports measures economic.","sourcePage":54},{"id":"aphug-u6-c50","front":"Trade surplus","back":"A condition in which the value of a country's exports exceeds the value of its imports.","sourcePage":54},{"id":"aphug-u6-c51","front":"Trade deficit","back":"import value exceeds the export value - Imports > Exports","sourcePage":54},{"id":"aphug-u6-c52","front":"Standard of living","back":"Measured by services of productivity that provides for the population.","sourcePage":54},{"id":"aphug-u6-c53","front":"Human development index","back":"Designed by the UN to measure the development of states based on # of social indicators and economic production.","sourcePage":54},{"id":"aphug-u6-c54","front":"Gini coefficient","back":"Measures the level of income disparity between countries' richest and poorest population.","sourcePage":54},{"id":"aphug-u6-c55","front":"Gender-Related Development Index","back":"Same indicated used in HDI but replaced with GDP per capita with income.","sourcePage":55},{"id":"aphug-u6-c56","front":"Gender equality","back":"equality of men and women 5 Stages of Pattern Growth - Traditional society - The economy is focused on primary production such as agriculture and fishing. - A precondition for takeoff - It when the country’s leadership begins to invest in the country’s wealth in infrastructure. - roads, ports, electrification - Takeoff - The economy begins to shift focus into a limited number of industrialized exports. - Drive to maturity - diffusion of technical advancements through the country - Age of mass…","sourcePage":55},{"id":"aphug-u6-c57","front":"Dependency theory","back":"Holds that most LDCs are highly dependent on foreign factories, investments, technology.","sourcePage":55},{"id":"aphug-u6-c60","front":"Transnational corporations","back":"Companies that conduct research, operate factories, and sell products in many countries.","sourcePage":55},{"id":"aphug-u6-c61","front":"Economic imperialism","back":"Nations controlled by private business interests that are independent but less-developed.","sourcePage":55},{"id":"aphug-u6-c65","front":"Import substitution","back":"Instead of buyindevleg First-world consumer products they produce within LDC.","sourcePage":56},{"id":"aphug-u6-c69","front":"Ecotourism","back":"Tourism of threatened ecosystems to observe wildlife and protect them.","sourcePage":56},{"id":"aphug-u6-c70","front":"Free-trade zones","back":"Areas that are controlled by corporations rather than the nation-state.","sourcePage":56},{"id":"aphug-u6-c71","front":"Tariffs","back":"Taxes on goods that cross international borders.","sourcePage":56},{"id":"aphug-u6-c72","front":"Command economy","back":"All economic production managed and planned by the central government.","sourcePage":56},{"id":"aphug-u6-c73","front":"Special economic zones (SEZs)","back":"Foreign firms were allowed to build factories in coastal port cities.","sourcePage":56},{"id":"aphug-u6-c74","front":"Export processing zone","back":"Defined as port locations where foreign firms are given special tax privileges to incentivize trade. - Ex: SEZs","sourcePage":56},{"id":"aphug-u6-c75","front":"Core","back":"Nation that is the most developed economies and is influential to the world.","sourcePage":56},{"id":"aphug-u6-c76","front":"Periphery","back":"In world-systems theory, less-developed countries that supply raw materials and low-cost labor and have limited global influence.","sourcePage":56},{"id":"aphug-u6-c77","front":"Semi-periphery","back":"In world-systems theory, countries with characteristics of both core and peripheral economies that mediate between the two.","sourcePage":56},{"id":"aphug-u6-c78","front":"Industrial location","back":"Selection of optimal factory location that minimizes land, labor, resource, and transportation costs.","sourcePage":57},{"id":"aphug-u6-c79","front":"Bulk-reducing manufacturing","back":"Manufacturing in which the finished product weighs less or occupies less volume than its inputs, encouraging factories to locate near raw materials.","sourcePage":57},{"id":"aphug-u6-c80","front":"Bulk-gaining manufacturing","back":"Manufacturing in which the finished product gains weight or volume, encouraging factories to locate near markets to reduce delivery costs.","sourcePage":57},{"id":"aphug-u6-c81","front":"Distance elastic","back":"Can be transported over short or long distances to the steel plant.","sourcePage":57},{"id":"aphug-u6-c82","front":"Mini mills","back":"run by companies such as NUCOR - Located in old steel-producing cities","sourcePage":57},{"id":"aphug-u6-c83","front":"Shelf-life","back":"The length of time a product can be stored before it becomes unsafe, unusable, or loses acceptable quality.","sourcePage":57},{"id":"aphug-u6-c84","front":"Decentralized network","back":"Keep fresh products in stores longer by reducing transportation time.","sourcePage":57},{"id":"aphug-u6-c85","front":"Ubiquitous industry","back":"Bread production is so decentralized that bakeries are found in all cities.","sourcePage":57},{"id":"aphug-u6-c86","front":"Supply chain","back":"Exists when parts are assembled into components that are joined together to create larger finished products.","sourcePage":57},{"id":"aphug-u6-c87","front":"Fordist production","back":"Relied on a single company owning all aspects of production from the steel manufacturer to advertising.","sourcePage":57},{"id":"aphug-u6-c88","front":"Post-Fordist era","back":"Car companies changed and became independent on large networks of regional supply chains.","sourcePage":57},{"id":"aphug-u6-c89","front":"Outsourcing","back":"Common in auto parts and companies reply to several other companies to provide vehicle components.","sourcePage":57},{"id":"aphug-u6-c90","front":"Just in time production","back":"Suppliers send parts to assembly plants on an as-needed basis.","sourcePage":57},{"id":"aphug-u6-c91","front":"Retail services","back":"Services that provide goods for sale to consumers.","sourcePage":57},{"id":"aphug-u6-c92","front":"The spatial margin of profitability","back":"Defined areas of maximization - Areas where local demand for service creates higher revenue than local costs.","sourcePage":57},{"id":"aphug-u6-c93","front":"Footloose industry","back":"Business locations that are not tied to resources or transportation.","sourcePage":58},{"id":"aphug-u6-c94","front":"Creative class","back":"Highly educated workers in knowledge, design, technology, arts, research, and professional fields associated with innovation and urban growth.","sourcePage":58},{"id":"aphug-u6-c95","front":"Agglomeration economies","back":"Exist where firms with related or similar products are located together in clusters or regions.","sourcePage":58},{"id":"aphug-u6-c96","front":"Deglomeration","back":"When a location is overloaded with similar firms and services.","sourcePage":58},{"id":"aphug-u6-c97","front":"Unionized-labor states","back":"Higher payroll and benefit costs which were ingrained into state workforce regulations.","sourcePage":58},{"id":"aphug-u6-c98","front":"Right-to-work states","back":"Regulation does not favor union and does not impact pay benefit costs.","sourcePage":58},{"id":"aphug-u6-c99","front":"Economies of scale","back":"Reductions in average production cost that occur as a firm increases output and spreads fixed costs across more units.","sourcePage":58},{"id":"aphug-u6-c100","front":"Economies of scope","back":"Cost savings gained when a firm produces multiple related products or services using shared resources, technology, or distribution.","sourcePage":58},{"id":"aphug-u6-c101","front":"Product cycle","back":"The stages a product passes through from introduction and growth to maturity and eventual decline or relocation of production.","sourcePage":58}],"questions":[],"feynmanPrompts":[]},{"id":"aphug-unit-7","name":"AP Human Geography · Unit 7","shortName":"Unit 7","builtIn":true,"sourceTitle":"AP Human Geography Guide — Simple Studies","sourceUrl":"https://uploads-ssl.webflow.com/605fe570e5454a357d1e1811/609eca6f9b9577dbf6455213_SS-APHuG.pdf","cards":[{"id":"aphug-u7-c1","front":"Central place theory","back":"Holds that all market areas are focused on a central settlement which is a place of exchange and service.","sourcePage":61},{"id":"aphug-u7-c2","front":"Market hinterland","back":"The surrounding area served by a central place, from which customers travel to obtain its goods and services.","sourcePage":61},{"id":"aphug-u7-c3","front":"Urban hierarchy","back":"The ranking of settlements by population, market area, and the number and complexity of services they provide.","sourcePage":61},{"id":"aphug-u7-c4","front":"Threshold in central place theory","back":"The minimum number of customers needed to support a particular service or business.","sourcePage":61},{"id":"aphug-u7-c5","front":"Range in central place theory","back":"The maximum distance consumers are willing to travel to obtain a particular good or service.","sourcePage":61},{"id":"aphug-u7-c6","front":"Growth poles","back":"Area of a country where specific industries bring employees and thus cause economic growth with the industry, housing market, and local economy.","sourcePage":61},{"id":"aphug-u7-c10","front":"Clustered rural settlements","back":"A community that has all residential farm structures of numerous households all aligned or arranged closely together.","sourcePage":61},{"id":"aphug-u7-c11","front":"Dispersed rural settlement","back":"Households are more separated from one another significantly.","sourcePage":61},{"id":"aphug-u7-c13","front":"Linear settlements","back":"Settlements arranged in a line along a road, river, coastline, or valley because access follows that corridor.","sourcePage":61},{"id":"aphug-u7-c14","front":"Urban site","back":"The physical characteristics of the land where a city developed, such as terrain, water supply, defensibility, and access to resources.","sourcePage":61},{"id":"aphug-u7-c15","front":"Urban situation","back":"A city's location relative to other places and transportation networks, which influences trade, accessibility, and growth.","sourcePage":62},{"id":"aphug-u7-c18","front":"Gentrification","back":"replaced or renovated - Economic reinvestment into existing buildings","sourcePage":62},{"id":"aphug-u7-c19","front":"Garden city movement","back":"Were designed to like European farmhouses with front lawns. - Built for the middle class of Chicago","sourcePage":62},{"id":"aphug-u7-c20","front":"Suburbanization","back":"The movement of population, housing, and economic activity from central cities to surrounding suburban areas.","sourcePage":62},{"id":"aphug-u7-c23","front":"Bid-rent curve","back":"A graph that shows the cost-to-distance relationship of real estate prices in an urban landscape setting.","sourcePage":62},{"id":"aphug-u7-c24","front":"Sector model","back":"Urban structure proposed in 1939 by theorist Homer Hoyt.","sourcePage":62},{"id":"aphug-u7-c25","front":"Ethnic neighborhoods","back":"The result of immigration to industrial cities over previous decades.","sourcePage":62},{"id":"aphug-u7-c26","front":"White flight","back":"The movement of white residents from racially diversifying central cities to suburbs, particularly in the United States during the twentieth century.","sourcePage":62},{"id":"aphug-u7-c28","front":"Multiple nuclei model","back":"Revolutionary step in the conceptualization of the Anglo-American city.","sourcePage":62},{"id":"aphug-u7-c31","front":"Post-industrial city","back":"A city whose economy has shifted from manufacturing toward services, information, finance, technology, and knowledge-based employment.","sourcePage":62},{"id":"aphug-u7-c32","front":"Latin America city model","back":"First represented by Larry Ford and Ernest Griffin in 1980.","sourcePage":62},{"id":"aphug-u7-c35","front":"Squatters","back":"People who settle on land that they don't own.","sourcePage":62},{"id":"aphug-u7-c36","front":"Land invasion","back":"Setter in a new area overnight with a large number of families to avoid retributions from landowners.","sourcePage":63},{"id":"aphug-u7-c37","front":"Land tenure","back":"Legal right or title to the land they build their homes on.","sourcePage":63},{"id":"aphug-u7-c38","front":"Basic-sector services","back":"Economic activities that bring income into a settlement by selling goods or services to customers outside the local area.","sourcePage":63},{"id":"aphug-u7-c39","front":"Nonbasic-sector services","back":"Economic activities that primarily serve the local population and circulate income already present within the settlement.","sourcePage":63},{"id":"aphug-u7-c41","front":"Sprawl","back":"Defined as the expansion of housing, transportation, and commercial development.","sourcePage":63},{"id":"aphug-u7-c42","front":"Growth boundaries","back":"Lines limiting outward urban development to contain sprawl, protect farmland, and encourage denser development.","sourcePage":63},{"id":"aphug-u7-c43","front":"Counter urbanization","back":"is the movement of inner-city suburban residents to rural areas to escape the congestion.","sourcePage":63},{"id":"aphug-u7-c44","front":"Edge city","back":"An area on the outer parts of a city that has a lot of office buildings, shopping malls, hotels, etc.","sourcePage":63},{"id":"aphug-u7-c47","front":"Colonial cities","back":"Cities with origins as centers of colonial trade of administration.","sourcePage":63},{"id":"aphug-u7-c49","front":"Break-in-bulk points","back":"Ships offloaded and packed with outgoing trade.","sourcePage":63},{"id":"aphug-u7-c51","front":"Gateway cities","back":"Cities that serve as major entry points for migrants, trade, capital, or ideas into a country or region.","sourcePage":63},{"id":"aphug-u7-c52","front":"Entrepot","back":"Describes the port city in which goods are shipped and one price and shipped out to other reports at a higher price.","sourcePage":63},{"id":"aphug-u7-c53","front":"Megacity","back":"Metropolitan area with more than 10 million people.","sourcePage":63},{"id":"aphug-u7-c54","front":"Megapolis","back":"Merging of the urbanized area of two or more cities.","sourcePage":63},{"id":"aphug-u7-c55","front":"Conurbation","back":"A continuous urbanized region formed when expanding cities and towns grow together while retaining separate political identities.","sourcePage":63},{"id":"aphug-u7-c56","front":"World city","back":"A place that is a significant metropolitan area and a global center for finance trade and commerce. Urban hierarchy - World cities ranked in order of importance","sourcePage":63},{"id":"aphug-u7-c57","front":"Primate city","back":"The largest city in the country has at least twice the population of the country’s next largest city.","sourcePage":64},{"id":"aphug-u7-c58","front":"Urban primacy","back":"The dominance of one city over a country's urban system, often measured when the largest city is more than twice the size of the second largest.","sourcePage":64},{"id":"aphug-u7-c59","front":"Decentralization","back":"Is the social process of the population and industry migrating from urban places to suburban areas.","sourcePage":64},{"id":"aphug-u7-c60","front":"Segregation","back":"The spatial separation of social, racial, ethnic, or economic groups through law, discrimination, markets, or institutional practices.","sourcePage":64},{"id":"aphug-u7-c62","front":"Redlining","back":"Designating neighborhoods on company maps where home mortgage and ensure application would be denied automatically.","sourcePage":64},{"id":"aphug-u7-c63","front":"Restrictive covenants","back":"Private property agreements that historically prohibited sale or occupancy by specified racial, ethnic, or religious groups.","sourcePage":64},{"id":"aphug-u7-c64","front":"Racial steering","back":"Real estate agents advising customers to purchase homes in neighborhoods depending on their race.","sourcePage":64},{"id":"aphug-u7-c65","front":"Invasion and succession","back":"Long term turnover of neighborhood racial and ethnic composition.","sourcePage":64},{"id":"aphug-u7-c66","front":"Historic preservation","back":"Renovating homes in places such as Green Village in NYC and Georgetown in DC.","sourcePage":64},{"id":"aphug-u7-c67","front":"Traffic congestion","back":"When roads are crowded with cars leading to cars moving at slower speeds.","sourcePage":64},{"id":"aphug-u7-c68","front":"Mass transit","back":"High-capacity public transportation such as buses, subways, and commuter rail that moves many passengers along shared routes.","sourcePage":64},{"id":"aphug-u7-c69","front":"Mixed-use buildings","back":"Contain both housing and commercial space. - known as new urbanization","sourcePage":64}],"questions":[],"feynmanPrompts":[]}];
